import { Kysely, PostgresDialect } from "kysely";
import type { Transaction } from "kysely";
import pg from "pg";

import type { DB } from "./generated/database.js";
import { createPgPool, type PgPoolConfig } from "./pool.js";

/** Persistence schema interface generated by kysely-codegen (`DB`). */
export type Database = DB;

export type { Transaction };

/**
 * Creates a Kysely client over a new or provided `pg.Pool`. Persistence adapter
 * only — no domain logic and no schema sync. Table types come from
 * `src/generated/` (regenerate with `pnpm db:codegen`).
 */
export function createKysely(config: PgPoolConfig | { pool: pg.Pool }): Kysely<Database> {
  const pool = "pool" in config ? config.pool : createPgPool(config);
  return new Kysely<Database>({
    dialect: new PostgresDialect({ pool }),
  });
}
